import pandas as pd
import requests
import re
from datetime import datetime, timezone

now = datetime.now(timezone.utc)
now_epoch = int(now.timestamp())

BASE = 'https://site.api.espn.com/apis/site/v2/sports'

EXPECTED_COLUMNS = [
    'sport', 'league', 'team_abbr', 'team_name',
    'athlete_id', 'athlete_name', 'position', 'jersey',
    'status', 'injury_type', 'short_comment',
    'date_reported', 'date_reported_epoch',
    'severity_rank', '_epoch',
]

LEAGUES = [
    {'sport': 'football', 'league': 'nfl'},
    {'sport': 'basketball', 'league': 'nba'},
    {'sport': 'baseball', 'league': 'mlb'},
    {'sport': 'hockey', 'league': 'nhl'},
]

SEVERITY = {
    'OUT': 5, 'OUT_FOR_SEASON': 6, 'INJURED_RESERVE': 6,
    'DOUBTFUL': 4, 'QUESTIONABLE': 3, 'PROBABLE': 2,
    'DAY_TO_DAY': 3, 'DAY-TO-DAY': 3, 'GAME_TIME_DECISION': 3,
    'ACTIVE': 1, 'HEALTHY': 1,
}

def rank_severity(status):
    if not status:
        return 0
    s = status.upper().replace(' ', '_').replace('-', '_')
    return SEVERITY.get(s, 2)

rows = []
for li in range(len(LEAGUES)):
    ent = LEAGUES[li]
    sport = ent['sport']
    league = ent['league']
    try:
        resp = requests.get(
            BASE + '/' + sport + '/' + league + '/injuries',
            timeout=30,
        )
        if resp.status_code == 404:
            continue
        resp.raise_for_status()
        payload = resp.json() or {}
    except Exception:
        continue
    teams = payload.get('injuries', []) or []
    for ti in range(len(teams)):
        t = teams[ti]
        if not isinstance(t, dict):
            continue
        team_info = t.get('team', {}) or {}
        team_abbr = team_info.get('abbreviation', '')
        team_name = team_info.get('displayName', '') or t.get('displayName', '')
        injuries_list = t.get('injuries', []) or []
        for ii in range(len(injuries_list)):
            inj = injuries_list[ii]
            if not isinstance(inj, dict):
                continue
            athlete_info = inj.get('athlete', {}) or {}
            athlete_id = str(athlete_info.get('id', '') or '')
            if not athlete_id:
                links = athlete_info.get('links', []) or []
                for lk in range(len(links)):
                    link = links[lk]
                    href = link.get('href', '') if isinstance(link, dict) else ''
                    id_match = re.search(r'/id/(\d+)', href)
                    if id_match:
                        athlete_id = id_match.group(1)
                        break
            if not athlete_id:
                athlete_id = athlete_info.get('displayName', '')
            athlete_name = athlete_info.get('displayName', '')
            ath_team = athlete_info.get('team', {}) or {}
            if not isinstance(ath_team, dict):
                ath_team = {}
            row_team_abbr = team_abbr or ath_team.get('abbreviation', '')
            row_team_name = team_name or ath_team.get('displayName', '')
            position_info = athlete_info.get('position', {}) or {}
            position = position_info.get('abbreviation', '')
            jersey = athlete_info.get('jersey', '')
            status = inj.get('status', '')
            injury_type_info = inj.get('type', {}) or {}
            injury_type = injury_type_info.get('description', '') if isinstance(injury_type_info, dict) else str(injury_type_info)
            short_comment = inj.get('shortComment', '') or inj.get('longComment', '')
            date_reported = inj.get('date', '')
            date_reported_epoch = 0
            if date_reported:
                try:
                    date_reported_epoch = int(datetime.fromisoformat(date_reported.replace('Z', '+00:00')).timestamp())
                except Exception:
                    date_reported_epoch = 0
            rows.append({
                'sport': sport,
                'league': league,
                'team_abbr': row_team_abbr,
                'team_name': row_team_name,
                'athlete_id': str(athlete_id),
                'athlete_name': athlete_name,
                'position': position,
                'jersey': str(jersey),
                'status': status,
                'injury_type': injury_type,
                'short_comment': short_comment,
                'date_reported': date_reported,
                'date_reported_epoch': date_reported_epoch,
                'severity_rank': rank_severity(status),
                '_epoch': now_epoch,
            })

if rows:
    df = pd.DataFrame(rows, columns=EXPECTED_COLUMNS)
    df = df.sort_values(['severity_rank', 'date_reported_epoch'], ascending=[False, False]).reset_index(drop=True)
else:
    df = pd.DataFrame(columns=EXPECTED_COLUMNS)

GENERATE_RESULTS(df)
